        if (!panel || !trigger || !panelIsOpen(panel)) return
        var viewportWidth = document.documentElement.clientWidth || window.innerWidth
        var viewportHeight = window.innerHeight
        var margin = 12
        panel.style.width = Math.min(500, Math.max(0, viewportWidth - margin * 2)) + 'px'
        panel.style.maxHeight = Math.max(0, viewportHeight - margin * 2) + 'px'
        var anchor = trigger.getBoundingClientRect()
        var rect = panel.getBoundingClientRect()
        var left = clamp(anchor.right - rect.width, margin, Math.max(margin, viewportWidth - rect.width - margin))
        var above = anchor.top - rect.height - 10
        var top = above >= margin ? above : Math.min(anchor.bottom + 10, Math.max(margin, viewportHeight - rect.height - margin))
        panel.style.left = left + 'px'
        panel.style.top = Math.max(margin, top) + 'px'
