      var firstBandIndex = bandLevels.length ? levels.indexOf(bandLevels[0]) : 0
      var lastBandIndex = bandLevels.length ? levels.indexOf(bandLevels[bandLevels.length - 1]) : 0
      var bandFromFrac = count > 1 ? firstBandIndex / (count - 1) : 0
      var bandToFrac = count > 1 ? lastBandIndex / (count - 1) : 0
